import * as React from "react";
import "./icons.css";

/**
 * Consyst UI — иконки Font Awesome Solid, векторные (inline SVG).
 * Не требуют шрифта: одинаково работают на компьютере и телефоне.
 * Цвет наследуется от текста (currentColor), размер — проп size
 * (по умолчанию 16px, внутри контролов размер задаёт сам контрол).
 *
 * Иконки: Font Awesome Free 7 (https://fontawesome.com), лицензия CC BY 4.0.
 * Пути генерирует `npm run icons` (scripts/build-icons.mjs).
 *
 * Нужна иконка, которой нет в списке?
 *   import { faHouse } from "@fortawesome/free-solid-svg-icons";
 *   <Icon icon={faHouse} />
 */
export interface IconProps extends React.SVGAttributes<SVGSVGElement> {
  size?: number;
  color?: string;
  /** Вращение (для индикаторов загрузки) */
  spin?: boolean;
  /** Текст для скринридера. Без него иконка декоративная (aria-hidden) */
  label?: string;
}

/** [ширина, высота, path] или определение из пакета @fortawesome/*-svg-icons */
export type IconData = [number, number, string] | { icon: [number, number, unknown, unknown, string | string[]] };

export interface SvgIconProps extends IconProps {
  icon: IconData;
}

export function Icon({ icon, size, color, spin, label, className, style, ...props }: SvgIconProps) {
  const [w, h, d] = Array.isArray(icon) ? icon : [icon.icon[0], icon.icon[1], icon.icon[4]];
  const path = Array.isArray(d) ? d.join(" ") : d;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`0 0 ${w} ${h}`}
      fill="currentColor"
      aria-hidden={label ? undefined : true}
      role={label ? "img" : undefined}
      aria-label={label}
      focusable="false"
      className={["cs-icon", spin && "cs-icon--spin", className].filter(Boolean).join(" ")}
      style={{ width: `${w / h}em`, ...(size !== undefined && { fontSize: size }), color, ...style }}
      {...props}
    >
      <path d={path as string} />
    </svg>
  );
}

function createIcon(name: string, data: [number, number, string]) {
  const Component = (props: IconProps) => <Icon icon={data} {...props} />;
  Component.displayName = name;
  return Component;
}

